#include <stdio.h>

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int bills[8];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bills[i]) != 1) {
            return 1;
        }
    }

    int total = 0;
    for (int i = n - 1; i >= 0; i--) {
        printf("第 %d 笔是 %d 条喵\n", i + 1, bills[i]);
        total = total + bills[i];
    }
    printf("一共 %d 条喵\n", total);

    return 0;
}
